+  const stripePromise = getStripePromise();
+
+  // Build the Element appearance from the document's resolved tokens (light = editorial, .dark =
+  // Night) — the iframe can't read our CSS vars, so we pass the resolved values. Computed once on
+  // mount (client only); fall back to the light-theme token literals for safety.
+  const appearance = useMemo<Appearance>(() => {
+    if (typeof window === "undefined") return { theme: "stripe" };
+    const cs = getComputedStyle(document.documentElement);
+    const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
+    return {
+      theme: document.documentElement.classList.contains("dark") ? "night" : "stripe",
+      variables: {
+        colorPrimary: v("--ac", "#a65f10"),
+        colorBackground: v("--cd", "#fffdf8"),
+        colorText: v("--tx", "#1b1714"),
+        colorTextSecondary: v("--t2", "#6e6358"),
+        colorDanger: v("--warn", "#a44b34"),
+        fontFamily: v("--font-body", "system-ui, sans-serif"),
+        borderRadius: v("--r-sm", "12px"),
+        spacingUnit: "4px",
+      },
+    };
+  }, []);
+
+  const options = useMemo<StripeElementsOptions>(
+    () => ({ clientSecret, appearance }),
+    [clientSecret, appearance],
+  );
+
+  if (!stripePromise)
+    return (
+      <p role="alert" style={{ fontSize: 13, color: "var(--warn)", marginTop: 12 }}>
+        Card checkout is temporarily unavailable. Please try again shortly.
+      </p>
+    );
+
+  return (
+    <Elements stripe={stripePromise} options={options}>
+      <PayForm cartId={cartId} totals={totals} onEdit={onEdit} />
+    </Elements>
+  );
+}
+
+function PayForm({
+  cartId,
+  totals,
+  onEdit,
+}: {
+  cartId: string;
+  totals: CartTotals;
+  onEdit: () => void;
+}) {
+  const stripe = useStripe();
+  const elements = useElements();
+  const [submitting, setSubmitting] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  async function onSubmit(e: FormEvent) {
+    e.preventDefault();
+    if (!stripe || !elements) return; // Stripe.js still loading
+    setSubmitting(true);
+    setError(null);
+    // On success Stripe redirects to return_url; only an immediate (validation / declined-inline)
+    // error returns here. `error.message` from Stripe IS user-facing and safe to show.
+    const { error: payErr } = await stripe.confirmPayment({
+      elements,
+      confirmParams: {
+        return_url: `${window.location.origin}/track?cart=${encodeURIComponent(cartId)}`,
+      },
+    });
+    if (payErr) {
+      setError(payErr.message ?? "Payment couldn’t be completed. Please try another card.");
+      setSubmitting(false);
+    }
+  }
+
+  const dollars = `$${(totals.totalCents / 100).toFixed(2)}`;
+
+  return (
+    <form onSubmit={onSubmit}>
+      <PaymentElement options={{ layout: "tabs" }} />
+
+      {/* Polite, atomic live region for the pay error (the only announced status here). */}
+      <p
+        role="status"
+        aria-live="polite"
+        aria-atomic="true"
+        style={{ minHeight: 16, margin: "10px 0 0", fontSize: 13, color: "var(--warn)" }}
+      >
+        {error}
+      </p>
+
+      <button
+        type="submit"
+        disabled={!stripe || submitting}
+        aria-busy={submitting}
+        style={{
+          width: "100%",
+          marginTop: 12,
+          minHeight: 50,
+          borderRadius: 12,
+          border: "none",
+          background: "var(--ac)",
+          color: "var(--oa)",
+          fontWeight: 800,
+          fontSize: 16,
+          cursor: !stripe || submitting ? "default" : "pointer",
+          opacity: !stripe || submitting ? 0.7 : 1,
+        }}
+      >
+        {submitting ? "Processing…" : `Pay ${dollars}`}
+      </button>
+
+      <button
+        type="button"
+        onClick={onEdit}
+        disabled={submitting}
+        style={{
+          width: "100%",
+          marginTop: 8,
+          minHeight: 44,
+          borderRadius: 12,
+          border: "none",
+          background: "transparent",
+          color: "var(--t2)",
+          fontWeight: 700,
+          cursor: submitting ? "default" : "pointer",
+        }}
+      >
+        <span aria-hidden>←</span> Edit order
+      </button>
+    </form>
+  );
+}
