diff --git a/packages/core-settlement/__tests__/desktop-adapter.test.js b/packages/core-settlement/__tests__/desktop-adapter.test.js
new file mode 100644
index 0000000000..14733677a4
--- /dev/null
+++ b/packages/core-settlement/__tests__/desktop-adapter.test.js
@@ -0,0 +1,125 @@
+import { describe, it, expect, beforeAll, beforeEach } from "vitest";
+
+// 被测：桌面集成 adapter（位于 desktop-app-vue，relative require）
+const adapter = require("../../../desktop-app-vue/src/main/trade/settlement-escrow.js");
+const settlement = require("../lib/index.js");
+const ms = require("@chainlesschain/core-multisig");
+const ed = require("@chainlesschain/core-mtc/signers/ed25519");
+const { adaptSqlJsDb } = require("./helpers/sql-js-adapter.js");
+
+let SQL;
+beforeAll(async () => {
+  const initSqlJs = (await import("sql.js")).default;
+  SQL = await initSqlJs();
+});
+
+const LEDGER_ID = "fed-desktop";
+
+// 构造「桌面 DID 身份」：tweetnacl 风格 secret = seed(32)||pub(32)，
+// public_key_sign / private_key_ref 与桌面 did-keystore 解密后结构一致。
+function makeDesktopIdentity(did) {
+  const kp = ed.generateKeyPair(); // {publicKey:32, secretKey:32(seed)}
+  const nacl64 = Buffer.concat([Buffer.from(kp.secretKey), Buffer.from(kp.publicKey)]);
+  return {
+    did,
+    public_key_sign: Buffer.from(kp.publicKey).toString("base64"),
+    private_key_ref: JSON.stringify({ sign: nacl64.toString("base64"), encrypt: null, mnemonic: null }),
+  };
+}
+
+describe("settlement-escrow desktop adapter — DID 密钥桥", () => {
+  it("naclIdentityToMember 提取 seed 可签可验（64B nacl secret → 32B seed）", () => {
+    const id = makeDesktopIdentity("did:chainlesschain:alice");
+    const m = adapter.naclIdentityToMember(id);
+    expect(m.did).toBe("did:chainlesschain:alice");
+    expect(m.secretKey.length).toBe(32);
+    const core = { ledgerId: LEDGER_ID, kind: "transfer", from: "x", to: "y", amount: 1, nonce: "n" };
+    const sig = settlement.signEntry(core, m.secretKey);
+    expect(settlement.verifyEntry(core, sig, m.pubkeyJwk)).toBe(true);
+    // 篡改 → 验签失败
+    expect(settlement.verifyEntry({ ...core, amount: 2 }, sig, m.pubkeyJwk)).toBe(false);
+  });
+});
+
+describe("settlement-escrow desktop adapter — 完整流程 + core-multisig 门控", () => {
+  let db, se, buyer, seller, custodian, genesis;
+
+  beforeEach(() => {
+    db = adaptSqlJsDb(new SQL.Database());
+    genesis = adapter.naclIdentityToMember(makeDesktopIdentity("did:chainlesschain:genesis"));
+    custodian = adapter.naclIdentityToMember(makeDesktopIdentity("did:chainlesschain:custodian"));
+    buyer = adapter.naclIdentityToMember(makeDesktopIdentity("did:chainlesschain:buyer"));
+    seller = adapter.naclIdentityToMember(makeDesktopIdentity("did:chainlesschain:seller"));
+
+    // core-multisig 提案状态作为放款门控
+    ms.applySchema(db);
+    const msStore = ms.createStore(db);
+    const mgr = ms.createProposalsManager(msStore);
+    se = adapter.createSettlementEscrow({
+      settlement, db, ledgerId: LEDGER_ID, genesis, custodian,
+      proposalGate: (pid) => {
+        const p = msStore.getProposal(pid);
+        return { releasable: !!p && (p.state === "reached" || p.state === "consumed"), reason: p ? p.state : "not_found" };
+      },
+    });
+    se.registerMember(buyer);
+    se.registerMember(seller);
+    se.grant({ to: buyer.did, amount: 1000 });
+    se._mgr = mgr; // 测试用
+  });
+
+  it("买方押款 → multisig 未达阈放款被拦 → 达阈放款给卖方（守恒）", () => {
+    expect(se.balanceOf(buyer.did)).toBe(1000);
+
+    // 2-of-3 提案（买/卖/托管），买方发起
+    const policy = {
+      domain: "marketplace.knowledge.delivery", m: 2, n: 3,
+      members: [buyer, seller, custodian].map((x) => ({ did: x.did, alg: x.alg, pubkeyJwk: x.pubkeyJwk })),
+      requirePqc: false,
+    };
+    const proposed = se._mgr.propose({
+      domain: policy.domain, payload: { tx: "t1", amount: "180" }, policy,
+      initiator: { did: buyer.did, alg: buyer.alg, secretKey: buyer.secretKey },
+    });
+    const pid = proposed.proposal.id;
+
+    // 买方用桌面 DID 密钥（seed）签押款转账
+    const h = se.openHoldForTransaction({
+      transactionId: "t1", buyer: buyer.did, seller: seller.did, amount: 180,
+      proposalId: pid, buyerSecretKey: buyer.secretKey,
+    });
+    expect(h.ok).toBe(true);
+    expect(se.balanceOf(buyer.did)).toBe(820);
+    expect(se.balanceOf(custodian.did)).toBe(180);
+
+    // 未达阈 → 放款被拦
+    const early = se.release(h.holdId);
+    expect(early.ok).toBe(false);
+    expect(early.reason).toContain("proposal_not_releasable");
+    expect(se.balanceOf(seller.did)).toBe(0);
+
+    // 卖方第二签 → 达阈
+    const signed = se._mgr.sign({ proposalId: pid, signer: { did: seller.did, alg: seller.alg, secretKey: seller.secretKey } });
+    expect(signed.reachedThreshold).toBe(true);
+
+    // 放款成功
+    const r = se.release(h.holdId);
+    expect(r.ok).toBe(true);
+    expect(se.balanceOf(seller.did)).toBe(180);
+    expect(se.balanceOf(custodian.did)).toBe(0);
+    // 守恒
+    expect(se.balanceOf(buyer.did) + se.balanceOf(seller.did) + se.balanceOf(custodian.did)).toBe(1000);
+  });
+
+  it("退款路径把 credits 退回买方", () => {
+    const h = se.openHoldForTransaction({
+      transactionId: "t2", buyer: buyer.did, seller: seller.did, amount: 200, buyerSecretKey: buyer.secretKey,
+    });
+    expect(h.ok).toBe(true);
+    expect(se.balanceOf(buyer.did)).toBe(800);
+    const r = se.refund(h.holdId);
+    expect(r.ok).toBe(true);
+    expect(se.balanceOf(buyer.did)).toBe(1000);
+    expect(se.balanceOf(custodian.did)).toBe(0);
+  });
+});
diff --git a/packages/core-settlement/__tests__/escrow-atomicity.test.js b/packages/core-settlement/__tests__/escrow-atomicity.test.js
new file mode 100644
index 0000000000..8d6bb7bcb6
--- /dev/null
+++ b/packages/core-settlement/__tests__/escrow-atomicity.test.js
@@ -0,0 +1,102 @@
+import { describe, it, expect, beforeAll } from "vitest";
+
+const { applySchema } = require("../lib/schema.js");
+const { createLedger } = require("../lib/ledger.js");
+const { createEscrow } = require("../lib/escrow.js");
+const { signEntry } = require("../lib/signing.js");
+const { adaptSqlJsDb } = require("./helpers/sql-js-adapter.js");
+const { makeMember } = require("./helpers/fixtures.js");
+
+// 证明 escrow 每个写操作是原子的：若「转账成功、状态写失败」这种部分失败发生，
+// SAVEPOINT 会把转账一并回滚——钱不动、状态不变，可安全重试，杜绝 double-settle。
+
+let SQL;
+beforeAll(async () => {
+  const initSqlJs = (await import("sql.js")).default;
+  SQL = await initSqlJs();
+});
+
+const LEDGER_ID = "fed-1";
+
+function fundedSetup() {
+  const db = adaptSqlJsDb(new SQL.Database());
+  applySchema(db);
+  const genesis = makeMember("did:cc:genesis");
+  const ledger = createLedger(db, { ledgerId: LEDGER_ID, genesisDid: genesis.did });
+  ledger.registerMember(genesis);
+  const buyer = makeMember("did:cc:buyer");
+  const seller = makeMember("did:cc:seller");
+  const custodian = makeMember("did:cc:custodian");
+  [buyer, seller, custodian].forEach((m) => ledger.registerMember(m));
+  ledger.signAndMint({ to: buyer.did, amount: 1000, secretKey: genesis.secretKey });
+  return { db, ledger, genesis, buyer, seller, custodian };
+}
+
+function buyerFund(buyer, custodianDid, amount, nonce) {
+  const core = { ledgerId: LEDGER_ID, kind: "transfer", from: buyer.did, to: custodianDid, amount, nonce };
+  return { nonce, alg: buyer.alg, sig: signEntry(core, buyer.secretKey) };
+}
+
+// 包一层 db，让命中某个 SQL 子串的 statement.run() 抛错（模拟状态写失败），
+// 但同一连接的其它写（转账 INSERT）正常执行 → 触发「转账已落、状态没落」中间态。
+function faultyOn(db, sqlSubstr) {
+  return {
+    prepare(sql) {
+      const stmt = db.prepare(sql);
+      if (sql.includes(sqlSubstr)) {
+        return {
+          run: () => {
+            throw new Error("simulated write failure");
+          },
+          get: (...a) => stmt.get(...a),
+          all: (...a) => stmt.all(...a),
+        };
+      }
+      return stmt;
+    },
+    exec: (sql) => db.exec(sql),
+  };
+}
+
+describe("escrow — write atomicity (no double-settle / no lost money on partial failure)", () => {
+  it("a failed status UPDATE during release rolls back the payment", () => {
+    const { db, ledger, buyer, seller, custodian } = fundedSetup();
+    const faulty = faultyOn(db, "UPDATE escrow_holds");
+    const escrow = createEscrow(faulty, ledger, { custodianDid: custodian.did, custodianSecretKey: custodian.secretKey });
+
+    const h = escrow.openHold({ orderId: "o1", buyer: buyer.did, seller: seller.did, amount: 180, fund: buyerFund(buyer, custodian.did, 180, "n1") });
+    expect(h.ok).toBe(true);
+    expect(ledger.balanceOf(custodian.did)).toBe(180);
+
+    // release：转账会成功，但状态 UPDATE 被注入失败 → 整笔应回滚
+    const r = escrow.release(h.holdId);
+    expect(r.ok).toBe(false);
+    expect(r.reason).toContain("tx_failed");
+
+    // 钱没动：卖方仍 0、托管人仍持 180；hold 仍 held → 可安全重试
+    expect(ledger.balanceOf(seller.did)).toBe(0);
+    expect(ledger.balanceOf(custodian.did)).toBe(180);
+    expect(escrow.getHold(h.holdId).status).toBe("held");
+    // 守恒未被破坏
+    expect(ledger.balanceOf(buyer.did) + ledger.balanceOf(seller.did) + ledger.balanceOf(custodian.did)).toBe(ledger.totalMinted());
+    // 账本链仍自洽（被回滚的转账没留下半条记录）
+    expect(ledger.verifyChain()).toMatchObject({ ok: true });
+  });
+
+  it("after rollback, a subsequent healthy release succeeds exactly once", () => {
+    const { db, ledger, buyer, seller, custodian } = fundedSetup();
+    const faulty = faultyOn(db, "UPDATE escrow_holds");
+    const escrowBad = createEscrow(faulty, ledger, { custodianDid: custodian.did, custodianSecretKey: custodian.secretKey });
+    const h = escrowBad.openHold({ orderId: "o1", buyer: buyer.did, seller: seller.did, amount: 180, fund: buyerFund(buyer, custodian.did, 180, "n1") });
+    expect(escrowBad.release(h.holdId).ok).toBe(false); // 失败回滚
+
+    // 用健康 db 重试同一 hold → 恰好放款一次，不会因前次中间态而重复
+    const escrowOk = createEscrow(db, ledger, { custodianDid: custodian.did, custodianSecretKey: custodian.secretKey });
+    const r = escrowOk.release(h.holdId);
+    expect(r.ok).toBe(true);
+    expect(ledger.balanceOf(seller.did)).toBe(180);
+    expect(ledger.balanceOf(custodian.did)).toBe(0);
+    expect(escrowOk.getHold(h.holdId).status).toBe("released");
+    expect(escrowOk.release(h.holdId).ok).toBe(false); // 二次放款被状态闸拦
+  });
+});
