+"use strict";
+
+const ed25519Signer = require("@chainlesschain/core-mtc/signers/ed25519");
+
+/** 生成一个 Ed25519 成员（did + 公钥 jwk + 私钥）。 */
+function makeMember(did) {
+  const kp = ed25519Signer.generateKeyPair();
+  return {
+    did,
+    alg: ed25519Signer.ALG,
+    pubkeyJwk: ed25519Signer.makeJwk(kp.publicKey),
+    secretKey: kp.secretKey,
+  };
+}
+
+module.exports = { makeMember };
diff --git a/packages/core-settlement/__tests__/helpers/sql-js-adapter.js b/packages/core-settlement/__tests__/helpers/sql-js-adapter.js
new file mode 100644
index 0000000000..e47089e121
--- /dev/null
+++ b/packages/core-settlement/__tests__/helpers/sql-js-adapter.js
@@ -0,0 +1,61 @@
+"use strict";
+
+/**
+ * sql.js (WASM) → better-sqlite3 风格 API 适配，让单测无 native dep 即可跑。
+ * （与 core-multisig 同款 helper。）
+ */
+
+class SqlJsStmt {
+  constructor(db, sql) {
+    this._db = db;
+    this._sql = sql;
+  }
+  _normalizeParams(params) {
+    return params.map((p) => (Buffer.isBuffer(p) ? new Uint8Array(p) : p));
+  }
+  run(...params) {
+    const stmt = this._db.prepare(this._sql);
+    try {
+      stmt.bind(this._normalizeParams(params));
+      stmt.step();
+      return { changes: this._db.getRowsModified(), lastInsertRowid: 0 };
+    } finally {
+      stmt.free();
+    }
+  }
+  get(...params) {
+    const stmt = this._db.prepare(this._sql);
+    try {
+      stmt.bind(this._normalizeParams(params));
+      const has = stmt.step();
+      return has ? stmt.getAsObject() : undefined;
+    } finally {
+      stmt.free();
+    }
+  }
+  all(...params) {
+    const stmt = this._db.prepare(this._sql);
+    try {
+      stmt.bind(this._normalizeParams(params));
+      const rows = [];
+      while (stmt.step()) rows.push(stmt.getAsObject());
+      return rows;
+    } finally {
+      stmt.free();
+    }
+  }
+}
+
+function adaptSqlJsDb(sqlJsDb) {
+  return {
+    prepare(sql) {
+      return new SqlJsStmt(sqlJsDb, sql);
+    },
+    exec(sql) {
+      sqlJsDb.exec(sql);
+    },
+    _raw: sqlJsDb,
+  };
+}
+
+module.exports = { adaptSqlJsDb };
diff --git a/packages/core-settlement/__tests__/ledger-multiledger.test.js b/packages/core-settlement/__tests__/ledger-multiledger.test.js
new file mode 100644
index 0000000000..97c8d1af1e
--- /dev/null
+++ b/packages/core-settlement/__tests__/ledger-multiledger.test.js
@@ -0,0 +1,84 @@
+import { describe, it, expect, beforeAll, beforeEach } from "vitest";
+
+const { applySchema } = require("../lib/schema.js");
+const { createLedger } = require("../lib/ledger.js");
+const { adaptSqlJsDb } = require("./helpers/sql-js-adapter.js");
+const { makeMember } = require("./helpers/fixtures.js");
+
+// 一个 DB 托管两个联邦账本（schema 每条都带 ledger_id）。校验读/链/nonce
+// 查询都按 ledger_id 隔离，不串账、不交织哈希链、不跨账本误拦 nonce。
+let SQL;
+beforeAll(async () => {
+  const initSqlJs = (await import("sql.js")).default;
+  SQL = await initSqlJs();
+});
+
+function setupTwoLedgers() {
+  const db = adaptSqlJsDb(new SQL.Database());
+  applySchema(db);
+  // 两账本共用同一 genesis 身份（同 did/同密钥），刻意制造跨账本碰撞场景
+  const genesis = makeMember("did:cc:genesis");
+  const alice = makeMember("did:cc:alice");
+  const bob = makeMember("did:cc:bob");
+
+  const A = createLedger(db, { ledgerId: "fed-A", genesisDid: genesis.did });
+  const B = createLedger(db, { ledgerId: "fed-B", genesisDid: genesis.did });
+  for (const L of [A, B]) [genesis, alice, bob].forEach((m) => L.registerMember(m));
+  return { db, A, B, genesis, alice, bob };
+}
+
+describe("ledger — multi-ledger isolation in one DB", () => {
+  let ctx;
+  beforeEach(() => {
+    ctx = setupTwoLedgers();
+  });
+
+  it("balances and totalMinted do not commingle across ledgers", () => {
+    const { A, B, genesis, alice, bob } = ctx;
+    A.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    B.signAndMint({ to: bob.did, amount: 500, secretKey: genesis.secretKey });
+
+    // 账本 A 只看得到自己的钱
+    expect(A.balanceOf(alice.did)).toBe(1000);
+    expect(A.balanceOf(bob.did)).toBe(0);
+    expect(A.totalMinted()).toBe(1000);
+
+    // 账本 B 只看得到自己的钱
+    expect(B.balanceOf(bob.did)).toBe(500);
+    expect(B.balanceOf(alice.did)).toBe(0);
+    expect(B.totalMinted()).toBe(500);
+
+    // 各自守恒
+    expect(A.balanceOf(alice.did) + A.balanceOf(bob.did)).toBe(A.totalMinted());
+    expect(B.balanceOf(alice.did) + B.balanceOf(bob.did)).toBe(B.totalMinted());
+  });
+
+  it("each ledger keeps an independent, verifiable hash chain", () => {
+    const { A, B, genesis, alice, bob } = ctx;
+    A.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    B.signAndMint({ to: bob.did, amount: 500, secretKey: genesis.secretKey });
+    A.signAndTransfer({ from: alice.did, to: bob.did, amount: 200, secretKey: alice.secretKey });
+
+    // 哈希链按账本独立计数（A 有 mint+transfer=2，B 只有 mint=1）
+    const va = A.verifyChain();
+    const vb = B.verifyChain();
+    expect(va).toMatchObject({ ok: true, count: 2 });
+    expect(vb).toMatchObject({ ok: true, count: 1 });
+    // head 各自指向本账本最后一条
+    expect(A.head()).not.toBe(B.head());
+  });
+
+  it("same signer may reuse a nonce across different ledgers (not a replay)", () => {
+    const { A, B, genesis, alice } = ctx;
+    // genesis 在 A 用 nonce "n1" mint
+    const a = A.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey, nonce: "n1" });
+    expect(a.ok).toBe(true);
+    // 同一 genesis 在 B 复用 nonce "n1"：签名 core 含 ledgerId → 字节不同，非重放 → 应放行
+    const b = B.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey, nonce: "n1" });
+    expect(b.ok).toBe(true);
+    // 但在同一账本内复用同一 nonce 仍被拦
+    const dup = A.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey, nonce: "n1" });
+    expect(dup.ok).toBe(false);
+    expect(dup.reason).toBe("nonce_reused");
+  });
+});
diff --git a/packages/core-settlement/__tests__/ledger-verifychain.test.js b/packages/core-settlement/__tests__/ledger-verifychain.test.js
new file mode 100644
index 0000000000..70cf018944
--- /dev/null
+++ b/packages/core-settlement/__tests__/ledger-verifychain.test.js
@@ -0,0 +1,104 @@
+import { describe, it, expect, beforeAll, beforeEach } from "vitest";
+import crypto from "crypto";
+
+const { applySchema } = require("../lib/schema.js");
+const { createLedger } = require("../lib/ledger.js");
+const { canonicalizeEntry, signEntry } = require("../lib/signing.js");
+const { adaptSqlJsDb } = require("./helpers/sql-js-adapter.js");
+const { makeMember } = require("./helpers/fixtures.js");
+
+// verifyChain 是篡改/伪造的后置检测：必须再校验「写入路径的每条不变量」，否则
+// 合谋节点/成员直接 INSERT 一条 well-formed（哈希对、签名对）的越权/透支条目就
+// 能瞒过再验。下面所有 forge 都构造**自洽哈希链 + 有效签名**，只违反某一条
+// 授权/经济规则，证明 verifyChain 不靠哈希/签名兜底也能识破。
+
+let SQL;
+beforeAll(async () => {
+  const initSqlJs = (await import("sql.js")).default;
+  SQL = await initSqlJs();
+});
+
+const LEDGER_ID = "fed-1";
+
+// 复刻 ledger.js 内部的 entry_hash 格式（攻击者也能算）：sha256(canonical || prev)
+function entryHash(canonicalBuf, prevHashHex) {
+  const h = crypto.createHash("sha256").update(canonicalBuf);
+  if (prevHashHex) h.update(Buffer.from(prevHashHex, "hex"));
+  return h.digest("hex");
+}
+
+function setup() {
+  const db = adaptSqlJsDb(new SQL.Database());
+  applySchema(db);
+  const genesis = makeMember("did:cc:genesis");
+  const alice = makeMember("did:cc:alice");
+  const bob = makeMember("did:cc:bob");
+  const ledger = createLedger(db, { ledgerId: LEDGER_ID, genesisDid: genesis.did });
+  [genesis, alice, bob].forEach((m) => ledger.registerMember(m));
+  return { db, ledger, genesis, alice, bob };
+}
+
+// 把一条自洽哈希链 + 有效签名、但可越权的条目直接塞进表（绕过 mint()/transfer()）。
+function injectForged(db, ledger, { kind, from, to, amount, nonce, signer }) {
+  const prev = ledger.head();
+  const core = { ledgerId: LEDGER_ID, kind, from: from == null ? null : from, to, amount, nonce };
+  const sig = signEntry(core, signer.secretKey); // 由 signer 真实签名（验签会过）
+  const eh = entryHash(canonicalizeEntry(core), prev);
+  db.prepare(
+    `INSERT INTO ledger_entries(entry_id, ledger_id, kind, from_did, to_did, amount, nonce, prev_hash, entry_hash, signer_did, alg, sig, created_at_ms)
+     VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`,
+  ).run("forge-" + nonce, LEDGER_ID, kind, from == null ? null : from, to, amount, nonce, prev, eh, signer.did, signer.alg, sig, 0);
+}
+
+describe("verifyChain — full invariant re-validation (anti node/member collusion)", () => {
+  let ctx;
+  beforeEach(() => {
+    ctx = setup();
+  });
+
+  it("honest chain still verifies (regression)", () => {
+    const { ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    ledger.signAndTransfer({ from: alice.did, to: bob.did, amount: 300, secretKey: alice.secretKey });
+    expect(ledger.verifyChain()).toMatchObject({ ok: true, count: 2 });
+  });
+
+  it("detects an unauthorized self-mint signed by a non-genesis member", () => {
+    const { db, ledger, genesis, alice } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey });
+    // alice 直接注入一条 mint 1000 给自己，由 alice 真实签名（签名会过、哈希自洽）
+    injectForged(db, ledger, { kind: "mint", from: null, to: alice.did, amount: 1000, nonce: "self-mint", signer: alice });
+    const v = ledger.verifyChain();
+    expect(v.ok).toBe(false);
+    expect(v.reason).toBe("mint_not_by_genesis");
+  });
+
+  it("detects a transfer whose signer is not the payer", () => {
+    const { db, ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: bob.did, amount: 1000, secretKey: genesis.secretKey });
+    // 注入 bob→alice 的转账，但由 alice 自己签 + signer_did=alice（冒名扣 bob 的钱）
+    injectForged(db, ledger, { kind: "transfer", from: bob.did, to: alice.did, amount: 500, nonce: "imp", signer: alice });
+    const v = ledger.verifyChain();
+    expect(v.ok).toBe(false);
+    expect(v.reason).toBe("transfer_signer_mismatch");
+  });
+
+  it("detects an injected overdraft (spending money that was never funded)", () => {
+    const { db, ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey });
+    // alice 自己签一条 alice→bob 500（远超余额 100），signer 合法、哈希自洽
+    injectForged(db, ledger, { kind: "transfer", from: alice.did, to: bob.did, amount: 500, nonce: "overdraw", signer: alice });
+    const v = ledger.verifyChain();
+    expect(v.ok).toBe(false);
+    expect(v.reason).toBe("insufficient_funds");
+  });
+
+  it("detects an injected non-positive amount", () => {
+    const { db, ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey });
+    injectForged(db, ledger, { kind: "transfer", from: alice.did, to: bob.did, amount: -50, nonce: "neg", signer: alice });
+    const v = ledger.verifyChain();
+    expect(v.ok).toBe(false);
+    expect(v.reason).toBe("invalid_amount");
+  });
+});
diff --git a/packages/core-settlement/__tests__/ledger.test.js b/packages/core-settlement/__tests__/ledger.test.js
new file mode 100644
index 0000000000..8d412fdf94
--- /dev/null
+++ b/packages/core-settlement/__tests__/ledger.test.js
@@ -0,0 +1,110 @@
+import { describe, it, expect, beforeAll, beforeEach } from "vitest";
+
+const { applySchema } = require("../lib/schema.js");
+const { createLedger } = require("../lib/ledger.js");
+const { signEntry } = require("../lib/signing.js");
+const { adaptSqlJsDb } = require("./helpers/sql-js-adapter.js");
+const { makeMember } = require("./helpers/fixtures.js");
+
+let SQL;
+beforeAll(async () => {
+  const initSqlJs = (await import("sql.js")).default;
+  SQL = await initSqlJs();
+});
+
+const LEDGER_ID = "fed-1";
+
+function setup() {
+  const db = adaptSqlJsDb(new SQL.Database());
+  applySchema(db);
+  const genesis = makeMember("did:cc:genesis");
+  const ledger = createLedger(db, { ledgerId: LEDGER_ID, genesisDid: genesis.did });
+  ledger.registerMember(genesis);
+  const alice = makeMember("did:cc:alice");
+  const bob = makeMember("did:cc:bob");
+  ledger.registerMember(alice);
+  ledger.registerMember(bob);
+  return { db, ledger, genesis, alice, bob };
+}
+
+describe("ledger — append-only signed transfer log", () => {
+  let ctx;
+  beforeEach(() => {
+    ctx = setup();
+  });
+
+  it("genesis mint credits a balance; conservation holds", () => {
+    const { ledger, genesis, alice } = ctx;
+    const r = ledger.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    expect(r.ok).toBe(true);
+    expect(ledger.balanceOf(alice.did)).toBe(1000);
+    expect(ledger.totalMinted()).toBe(1000);
+    // 守恒：alice 1000，其余 0
+    expect(ledger.balanceOf(alice.did) + ledger.balanceOf("did:cc:bob")).toBe(ledger.totalMinted());
+  });
+
+  it("rejects mint signed by non-genesis (no central-bank power for others)", () => {
+    const { ledger, alice } = ctx;
+    // alice 试图自己 mint：用 alice 私钥签 mint core，但 ledger 用 genesis 公钥验 → 失败
+    const core = { ledgerId: LEDGER_ID, kind: "mint", from: null, to: alice.did, amount: 999, nonce: "n1" };
+    const sig = signEntry(core, alice.secretKey);
+    const r = ledger.mint({ to: alice.did, amount: 999, nonce: "n1", sig });
+    expect(r.ok).toBe(false);
+    expect(r.reason).toBe("bad_genesis_sig");
+    expect(ledger.totalMinted()).toBe(0);
+  });
+
+  it("valid transfer moves balance and conserves total", () => {
+    const { ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    const r = ledger.signAndTransfer({ from: alice.did, to: bob.did, amount: 300, secretKey: alice.secretKey });
+    expect(r.ok).toBe(true);
+    expect(ledger.balanceOf(alice.did)).toBe(700);
+    expect(ledger.balanceOf(bob.did)).toBe(300);
+    expect(ledger.balanceOf(alice.did) + ledger.balanceOf(bob.did)).toBe(ledger.totalMinted());
+  });
+
+  it("rejects overdraft", () => {
+    const { ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 100, secretKey: genesis.secretKey });
+    const r = ledger.signAndTransfer({ from: alice.did, to: bob.did, amount: 101, secretKey: alice.secretKey });
+    expect(r.ok).toBe(false);
+    expect(r.reason).toBe("insufficient_funds");
+    expect(ledger.balanceOf(alice.did)).toBe(100);
+  });
+
+  it("rejects replay (reused nonce by same payer)", () => {
+    const { ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    const ok = ledger.signAndTransfer({ from: alice.did, to: bob.did, amount: 100, secretKey: alice.secretKey, nonce: "dup" });
+    expect(ok.ok).toBe(true);
+    const replay = ledger.signAndTransfer({ from: alice.did, to: bob.did, amount: 100, secretKey: alice.secretKey, nonce: "dup" });
+    expect(replay.ok).toBe(false);
+    expect(replay.reason).toBe("nonce_reused");
+    expect(ledger.balanceOf(bob.did)).toBe(100); // 只过一次
+  });
+
+  it("rejects a transfer with a forged signature (node cannot fabricate)", () => {
+    const { ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    // 用 bob 的私钥伪造 alice 的转账
+    const core = { ledgerId: LEDGER_ID, kind: "transfer", from: alice.did, to: bob.did, amount: 500, nonce: "x" };
+    const forged = signEntry(core, bob.secretKey);
+    const r = ledger.transfer({ from: alice.did, to: bob.did, amount: 500, nonce: "x", alg: alice.alg, sig: forged });
+    expect(r.ok).toBe(false);
+    expect(r.reason).toBe("bad_sig");
+  });
+
+  it("verifyChain passes for honest log and detects tampering", () => {
+    const { db, ledger, genesis, alice, bob } = ctx;
+    ledger.signAndMint({ to: alice.did, amount: 1000, secretKey: genesis.secretKey });
+    ledger.signAndTransfer({ from: alice.did, to: bob.did, amount: 250, secretKey: alice.secretKey });
+    expect(ledger.verifyChain()).toMatchObject({ ok: true });
+
+    // 节点篡改余额：直接改某条 amount → 链复算应识破
+    db.exec(`UPDATE ledger_entries SET amount = 9999 WHERE kind = 'transfer'`);
+    const v = ledger.verifyChain();
+    expect(v.ok).toBe(false);
+    expect(["hash_mismatch", "bad_sig"]).toContain(v.reason);
+  });
+});
diff --git a/packages/core-settlement/lib/escrow.js b/packages/core-settlement/lib/escrow.js
new file mode 100644
index 0000000000..20c08a1d76
--- /dev/null
+++ b/packages/core-settlement/lib/escrow.js
@@ -0,0 +1,126 @@
+"use strict";
+
+/**
+ * P1 结算核 — 托管人驱动的 escrow（§3.2 + §8.2）。
+ *
+ * 多签是「授权层」、托管人是「结算层」：
+ *  - openHold : 买方签名把 credits 转给 custodian（锁定），记一条 hold。
+ *  - release  : 经 proposalGate（multisig 是否达阈/consume）门控，达标才由
+ *               custodian 签名把 credits 转给 seller —— consume 即原子放款的
+ *               货款侧（加密交付侧 P3 再接 held_wrapped_key）。
+ *  - refund   : custodian 把 credits 退回买方。
+ *  - 状态闸（held→released/refunded）防重复放款（double-settle）。
+ *
+ * proposalGate 注入 → 本模块不硬依赖 core-multisig（解耦）；P1 接线/测试把它
+ * 接到 core-multisig 的 proposal 状态。
+ */
+
+const crypto = require("crypto");
+
+const _deps = {
+  now: () => Date.now(),
+  newId: () => crypto.randomUUID(),
+};
+
+/**
+ * @param {object} db
+ * @param {object} ledger  - createLedger(...) 实例
+ * @param {{custodianDid:string, custodianSecretKey:Buffer, proposalGate?:(proposalId:string)=>{releasable:boolean, reason?:string}}} opts
+ */
+function createEscrow(db, ledger, opts) {
+  if (!db || typeof db.prepare !== "function") throw new TypeError("createEscrow: db.prepare required");
+  if (!ledger) throw new TypeError("createEscrow: ledger required");
+  const custodianDid = opts && opts.custodianDid;
+  const custodianSecretKey = opts && opts.custodianSecretKey;
+  if (!custodianDid) throw new TypeError("createEscrow: custodianDid required");
+  // 无 gate 时默认放行（非 multisig 流程）；P1 接 core-multisig。
+  const proposalGate = (opts && opts.proposalGate) || (() => ({ releasable: true }));
+
+  // 原子性：每个写操作都做「转账 + 状态写」两步，必须同生共死，否则部分失败会留下
+  // 危险中间态——例如 release 已把货款转给卖方但 status 没翻 'released'，重试就**重复
+  // 放款**（double-settle）。用 SAVEPOINT 包裹（better-sqlite3 与 sql.js 都支持完整
+  // SQLite SQL，可嵌套在调用方事务内）：抛错则 ROLLBACK TO 把转账一并撤回，可安全重试。
+  function _atomic(label, fn) {
+    db.exec(`SAVEPOINT ${label}`);
+    try {
+      const out = fn();
+      db.exec(`RELEASE ${label}`);
+      return out;
+    } catch (e) {
+      try {
+        db.exec(`ROLLBACK TO ${label}`);
+        db.exec(`RELEASE ${label}`);
+      } catch (_e) {
+        /* best-effort：清理失败也不掩盖原始错误 */
+      }
+      return { ok: false, reason: "tx_failed:" + (e && e.message ? e.message : "error") };
+    }
+  }
+
+  function _normHold(row) {
+    if (!row) return null;
+    return {
+      id: row.id,
+      orderId: row.order_id,
+      buyerDid: row.buyer_did,
+      sellerDid: row.seller_did,
+      amount: Number(row.amount),
+      proposalId: row.proposal_id,
+      status: row.status,
+      fundEntryId: row.fund_entry_id,
+      settleEntryId: row.settle_entry_id,
+    };
+  }
+
+  function getHold(holdId) {
+    return _normHold(db.prepare(`SELECT * FROM escrow_holds WHERE id = ?`).get(holdId));
+  }
+
+  /**
+   * 买方押款入托管。fund = 买方对 buyer→custodian 转账的签名 {nonce, alg, sig}。
+   */
+  function openHold({ orderId, buyer, seller, amount, proposalId, fund }) {
+    return _atomic("cc_escrow_open", () => {
+      const r = ledger.transfer({ from: buyer, to: custodianDid, amount, nonce: fund.nonce, alg: fund.alg, sig: fund.sig });
+      if (!r.ok) return { ok: false, reason: "fund_failed:" + r.reason };
+      const id = _deps.newId();
+      db.prepare(
+        `INSERT INTO escrow_holds(id, order_id, buyer_did, seller_did, amount, proposal_id, status, fund_entry_id, created_at_ms)
+         VALUES(?,?,?,?,?,?, 'held', ?, ?)`,
+      ).run(id, orderId, buyer, seller, amount, proposalId == null ? null : proposalId, r.entryId, _deps.now());
+      return { ok: true, holdId: id, fundEntryId: r.entryId };
+    });
+  }
+
+  /** 经 multisig 门控放款给卖方。状态闸防 double-settle。 */
+  function release(holdId) {
+    const hold = getHold(holdId);
+    if (!hold) return { ok: false, reason: "hold_not_found" };
+    if (hold.status !== "held") return { ok: false, reason: "hold_state_" + hold.status };
+    const gate = proposalGate(hold.proposalId);
+    if (!gate || !gate.releasable) return { ok: false, reason: "proposal_not_releasable" + (gate && gate.reason ? ":" + gate.reason : "") };
+    return _atomic("cc_escrow_release", () => {
+      const r = ledger.signAndTransfer({ from: custodianDid, to: hold.sellerDid, amount: hold.amount, secretKey: custodianSecretKey });
+      if (!r.ok) return { ok: false, reason: "settle_failed:" + r.reason };
+      db.prepare(`UPDATE escrow_holds SET status='released', settle_entry_id=?, settled_at_ms=? WHERE id=?`).run(r.entryId, _deps.now(), holdId);
+      return { ok: true, entryId: r.entryId };
+    });
+  }
+
+  /** 退款给买方（交付失败/超时/争议判退）。状态闸防重复。 */
+  function refund(holdId) {
+    const hold = getHold(holdId);
+    if (!hold) return { ok: false, reason: "hold_not_found" };
+    if (hold.status !== "held") return { ok: false, reason: "hold_state_" + hold.status };
+    return _atomic("cc_escrow_refund", () => {
+      const r = ledger.signAndTransfer({ from: custodianDid, to: hold.buyerDid, amount: hold.amount, secretKey: custodianSecretKey });
+      if (!r.ok) return { ok: false, reason: "refund_failed:" + r.reason };
+      db.prepare(`UPDATE escrow_holds SET status='refunded', settle_entry_id=?, settled_at_ms=? WHERE id=?`).run(r.entryId, _deps.now(), holdId);
+      return { ok: true, entryId: r.entryId };
+    });
+  }
+
+  return { custodianDid, getHold, openHold, release, refund };
+}
+
+module.exports = { createEscrow, _deps };
diff --git a/packages/core-settlement/lib/index.js b/packages/core-settlement/lib/index.js
new file mode 100644
index 0000000000..52cc3a8924
--- /dev/null
+++ b/packages/core-settlement/lib/index.js
@@ -0,0 +1,22 @@
+"use strict";
+
+/**
+ * @chainlesschain/core-settlement — P1 结算核公开面。
+ * 联邦签名转账日志账本（ledger）+ 托管人 escrow（multisig 门控）。
+ */
+
+const schema = require("./schema.js");
+const signing = require("./signing.js");
+const { createLedger } = require("./ledger.js");
+const { createEscrow } = require("./escrow.js");
+
+module.exports = {
+  DDL: schema.DDL,
+  applySchema: schema.applySchema,
+  canonicalizeEntry: signing.canonicalizeEntry,
+  signEntry: signing.signEntry,
+  verifyEntry: signing.verifyEntry,
+  ALG: signing.ALG,
+  createLedger,
+  createEscrow,
+};
diff --git a/packages/core-settlement/lib/ledger.js b/packages/core-settlement/lib/ledger.js
new file mode 100644
index 0000000000..15cf1fbb12
--- /dev/null
+++ b/packages/core-settlement/lib/ledger.js
@@ -0,0 +1,213 @@
+"use strict";
+
+/**
+ * P1 结算核 — 联邦签名转账日志账本（§8.2 决策落地）。
+ *
+ * 核心性质：账本不存「可写余额表」，存「只追加的签名转账日志」。
+ *  - 余额 = fold(日志)：balanceOf = Σ(到账) − Σ(出账)
+ *  - 每笔 transfer 由付款方签名；mint（grant）只由 genesis 签名 → 节点无有效
+ *    签名伪造不了转账、也凭空印不了钱（修正 v1.3「节点=央行」漏洞）。
+ *  - 全局哈希链（entry_hash = sha256(canonical || prev_hash)）→ 重排/插入可检测。
+ *  - 守恒：Σ 全体余额 == totalMinted（mint 是唯一增发源，由 genesis 规则约束）。
+ *
+ * DB 无关：接受 better-sqlite3(-multiple-ciphers) 或 sql.js（同 prepare/run/get/all）。
+ */
+
+const crypto = require("crypto");
+const { canonicalizeEntry, signEntry, verifyEntry } = require("./signing.js");
+
+const _deps = {
+  now: () => Date.now(),
+  newId: () => crypto.randomUUID(),
+  newNonce: () => crypto.randomBytes(12).toString("hex"),
+};
+
+function entryHash(canonicalBuf, prevHashHex) {
+  const h = crypto.createHash("sha256").update(canonicalBuf);
+  if (prevHashHex) h.update(Buffer.from(prevHashHex, "hex"));
+  return h.digest("hex");
+}
+
+/**
+ * @param {object} db   - SQLite-like handle（applySchema 已跑过）
+ * @param {{ledgerId:string, genesisDid:string}} opts
+ */
+function createLedger(db, opts) {
+  if (!db || typeof db.prepare !== "function") {
+    throw new TypeError("createLedger: db.prepare is required");
+  }
+  const ledgerId = opts && opts.ledgerId;
+  const genesisDid = opts && opts.genesisDid;
+  if (!ledgerId) throw new TypeError("createLedger: ledgerId required");
+  if (!genesisDid) throw new TypeError("createLedger: genesisDid required");
+
+  function registerMember({ did, alg, pubkeyJwk }) {
+    db.prepare(
+      `INSERT OR REPLACE INTO settlement_members(did, alg, pubkey_jwk) VALUES(?,?,?)`,
+    ).run(did, alg, JSON.stringify(pubkeyJwk));
+  }
+
+  function getMember(did) {
+    const row = db
+      .prepare(`SELECT did, alg, pubkey_jwk FROM settlement_members WHERE did = ?`)
+      .get(did);
+    if (!row) return null;
+    return { did: row.did, alg: row.alg, pubkeyJwk: JSON.parse(row.pubkey_jwk) };
+  }
+
+  // 所有读/链查询都按 ledger_id 隔离：一个 DB 可托管多个联邦账本（schema 每条
+  // 都带 ledger_id），balanceOf/totalMinted/head/verifyChain/nonceUsed 必须只看
+  // 本账本的条目，否则多账本共享 DB 时余额会串、哈希链会交织。
+  function head() {
+    const row = db
+      .prepare(`SELECT entry_hash FROM ledger_entries WHERE ledger_id = ? ORDER BY seq DESC LIMIT 1`)
+      .get(ledgerId);
+    return row ? row.entry_hash : null;
+  }
+
+  function balanceOf(did) {
+    const inc = Number(
+      db.prepare(`SELECT COALESCE(SUM(amount),0) AS s FROM ledger_entries WHERE ledger_id = ? AND to_did = ?`).get(ledgerId, did).s,
+    );
+    const dec = Number(
+      db.prepare(`SELECT COALESCE(SUM(amount),0) AS s FROM ledger_entries WHERE ledger_id = ? AND from_did = ?`).get(ledgerId, did).s,
+    );
+    return inc - dec;
+  }
+
+  function totalMinted() {
+    return Number(
+      db.prepare(`SELECT COALESCE(SUM(amount),0) AS s FROM ledger_entries WHERE ledger_id = ? AND kind = 'mint'`).get(ledgerId).s,
+    );
+  }
+
+  // nonce 唯一性按 (ledger_id, signer_did) 作用域：同一签名者在不同账本复用同一
+  // nonce 不是重放（签名 core 含 ledgerId → 字节不同），故不应跨账本误拦。
+  function nonceUsed(signerDid, nonce) {
+    return !!db
+      .prepare(`SELECT 1 FROM ledger_entries WHERE ledger_id = ? AND signer_did = ? AND nonce = ? LIMIT 1`)
+      .get(ledgerId, signerDid, nonce);
+  }
+
+  function _append({ kind, from, to, amount, nonce, alg, sig, signerDid }) {
+    const core = { ledgerId, kind, from: from == null ? null : from, to, amount, nonce };
+    const prev = head();
+    const eh = entryHash(canonicalizeEntry(core), prev);
+    const id = _deps.newId();
+    db.prepare(
+      `INSERT INTO ledger_entries(entry_id, ledger_id, kind, from_did, to_did, amount, nonce, prev_hash, entry_hash, signer_did, alg, sig, created_at_ms)
+       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`,
+    ).run(id, ledgerId, kind, from == null ? null : from, to, amount, nonce, prev, eh, signerDid, alg, sig, _deps.now());
+    return { entryId: id, entryHash: eh };
+  }
+
+  /** mint（grant）— 仅 genesis 可，外部已签 sig 由 genesis 公钥验。 */
+  function mint({ to, amount, nonce, sig }) {
+    if (!Number.isInteger(amount) || amount <= 0) return { ok: false, reason: "invalid_amount" };
+    const gm = getMember(genesisDid);
+    if (!gm) return { ok: false, reason: "genesis_not_registered" };
+    if (nonceUsed(genesisDid, nonce)) return { ok: false, reason: "nonce_reused" };
+    const core = { ledgerId, kind: "mint", from: null, to, amount, nonce };
+    if (!verifyEntry(core, sig, gm.pubkeyJwk)) return { ok: false, reason: "bad_genesis_sig" };
+    return { ok: true, ..._append({ kind: "mint", from: null, to, amount, nonce, alg: gm.alg, sig, signerDid: genesisDid }) };
+  }
+
+  /** transfer — 外部已签（付款方），验签 + nonce + 余额 后追加。 */
+  function transfer({ from, to, amount, nonce, alg, sig }) {
+    if (!Number.isInteger(amount) || amount <= 0) return { ok: false, reason: "invalid_amount" };
+    if (from === to) return { ok: false, reason: "self_transfer" };
+    const fm = getMember(from);
+    if (!fm) return { ok: false, reason: "unknown_payer" };
+    if (alg && fm.alg !== alg) return { ok: false, reason: "alg_mismatch" };
+    if (nonceUsed(from, nonce)) return { ok: false, reason: "nonce_reused" };
+    const core = { ledgerId, kind: "transfer", from, to, amount, nonce };
+    if (!verifyEntry(core, sig, fm.pubkeyJwk)) return { ok: false, reason: "bad_sig" };
+    if (balanceOf(from) < amount) return { ok: false, reason: "insufficient_funds" };
+    return { ok: true, ..._append({ kind: "transfer", from, to, amount, nonce, alg: fm.alg, sig, signerDid: from }) };
+  }
+
+  /** 便利：本地持密钥者（custodian / 测试）签名并转账。 */
+  function signAndTransfer({ from, to, amount, secretKey, nonce }) {
+    const m = getMember(from);
+    if (!m) return { ok: false, reason: "unknown_payer" };
+    const n = nonce || _deps.newNonce();
+    const core = { ledgerId, kind: "transfer", from, to, amount, nonce: n };
+    const sig = signEntry(core, secretKey);
+    return transfer({ from, to, amount, nonce: n, alg: m.alg, sig });
+  }
+
+  /** 便利：genesis 签名并 mint。 */
+  function signAndMint({ to, amount, secretKey, nonce }) {
+    const n = nonce || _deps.newNonce();
+    const core = { ledgerId, kind: "mint", from: null, to, amount, nonce: n };
+    const sig = signEntry(core, secretKey);
+    return mint({ to, amount, nonce: n, sig });
+  }
+
+  /**
+   * 全链复算 = 完整再校验「写入路径强制的每条不变量」，不只是哈希+签名。这样即使
+   * 有节点/成员合谋绕过 mint()/transfer() 直接 INSERT well-formed 行，再验也能识破
+   * （支撑设计「节点伪造不了转账、印不了钱」的核心安全声明）：
+   *   1) 哈希链续接 + entry_hash 自洽（重排/插入/改值可检测）
+   *   2) 金额必须正整数（防注入 amount<=0 / 非整数 偷钱）
+   *   3) 授权规则：mint 必由 genesis 签且无 from；transfer 的 signer 必等于 from、
+   *      不可自转（防越权增发 / 冒名转账）
+   *   4) 签名对（signer 注册公钥验 core）
+   *   5) 经济守恒：按 seq 折叠余额，任一时刻 from 余额不足即拦（防注入透支花钱）
+   */
+  function verifyChain() {
+    const rows = db.prepare(`SELECT * FROM ledger_entries WHERE ledger_id = ? ORDER BY seq ASC`).all(ledgerId);
+    let prev = null;
+    const bal = new Map();
+    const get = (d) => bal.get(d) || 0;
+    for (const row of rows) {
+      const from = row.from_did == null ? null : row.from_did;
+      const amount = Number(row.amount);
+      const core = { ledgerId: row.ledger_id, kind: row.kind, from, to: row.to_did, amount, nonce: row.nonce };
+      // 1) 链接续 + 哈希自洽
+      if ((row.prev_hash || null) !== (prev || null)) return { ok: false, reason: "chain_break", at: row.entry_id };
+      if (entryHash(canonicalizeEntry(core), prev) !== row.entry_hash) return { ok: false, reason: "hash_mismatch", at: row.entry_id };
+      // 2) 金额正整数
+      if (!Number.isInteger(amount) || amount <= 0) return { ok: false, reason: "invalid_amount", at: row.entry_id };
+      // 3) 授权规则
+      if (core.kind === "mint") {
+        if (from !== null) return { ok: false, reason: "mint_has_from", at: row.entry_id };
+        if (row.signer_did !== genesisDid) return { ok: false, reason: "mint_not_by_genesis", at: row.entry_id };
+      } else if (core.kind === "transfer") {
+        if (from == null) return { ok: false, reason: "transfer_missing_from", at: row.entry_id };
+        if (from === core.to) return { ok: false, reason: "self_transfer", at: row.entry_id };
+        if (row.signer_did !== from) return { ok: false, reason: "transfer_signer_mismatch", at: row.entry_id };
+      } else {
+        return { ok: false, reason: "unknown_kind", at: row.entry_id };
+      }
+      // 4) 签名对
+      const member = getMember(row.signer_did);
+      if (!member || !verifyEntry(core, row.sig, member.pubkeyJwk)) return { ok: false, reason: "bad_sig", at: row.entry_id };
+      // 5) 经济守恒：余额折叠（mint 增发到 to；transfer 必须 from 余额充足）
+      if (core.kind === "transfer") {
+        if (get(from) < amount) return { ok: false, reason: "insufficient_funds", at: row.entry_id };
+        bal.set(from, get(from) - amount);
+      }
+      bal.set(core.to, get(core.to) + amount);
+      prev = row.entry_hash;
+    }
+    return { ok: true, count: rows.length };
+  }
+
+  return {
+    ledgerId,
+    genesisDid,
+    registerMember,
+    getMember,
+    mint,
+    transfer,
+    signAndTransfer,
+    signAndMint,
+    balanceOf,
+    totalMinted,
+    head,
+    verifyChain,
+  };
+}
+
+module.exports = { createLedger, _deps };
diff --git a/packages/core-settlement/lib/schema.js b/packages/core-settlement/lib/schema.js
new file mode 100644
index 0000000000..cbe587c02b
--- /dev/null
+++ b/packages/core-settlement/lib/schema.js
@@ -0,0 +1,66 @@
+"use strict";
+
+/**
+ * P1 结算核 — SQLite schema。兼容 better-sqlite3(-multiple-ciphers) + sql.js
+ * （`db.exec` 都接多语句 SQL string），与 core-multisig 同款 DB 无关风格。
+ *
+ * 三表：
+ *  - settlement_members : did → 公钥（验转账签名用；did↔pubkey 绑定由 DID 层建立）
+ *  - ledger_entries     : 只追加签名转账日志（余额 = fold(log)，无可写余额表）
+ *  - escrow_holds       : 托管人持有（buyer→custodian 锁定，consume 时 →seller）
+ */
+
+const DDL = `
+CREATE TABLE IF NOT EXISTS settlement_members (
+  did        TEXT PRIMARY KEY,
+  alg        TEXT NOT NULL,
+  pubkey_jwk TEXT NOT NULL
+);
+
+CREATE TABLE IF NOT EXISTS ledger_entries (
+  seq           INTEGER PRIMARY KEY AUTOINCREMENT,
+  entry_id      TEXT UNIQUE NOT NULL,
+  ledger_id     TEXT NOT NULL,
+  kind          TEXT NOT NULL,          -- 'mint' | 'transfer'
+  from_did      TEXT,                   -- NULL for mint
+  to_did        TEXT NOT NULL,
+  amount        INTEGER NOT NULL,       -- credits, integer > 0
+  nonce         TEXT NOT NULL,
+  prev_hash     TEXT,                   -- 前一条 entry_hash（全局哈希链）
+  entry_hash    TEXT NOT NULL,          -- sha256(canonical || prev_hash)
+  signer_did    TEXT NOT NULL,          -- transfer=from / mint=genesis
+  alg           TEXT NOT NULL,
+  sig           BLOB NOT NULL,
+  created_at_ms INTEGER NOT NULL
+);
+CREATE INDEX IF NOT EXISTS idx_ledger_from ON ledger_entries(from_did);
+CREATE INDEX IF NOT EXISTS idx_ledger_to   ON ledger_entries(to_did);
+-- 同一账本内同一签名者 nonce 唯一 → 防重放（transfer 与 mint 都覆盖）。
+-- 含 ledger_id：跨账本同 nonce 不是重放（签名 core 含 ledgerId），不应误拦。
+CREATE UNIQUE INDEX IF NOT EXISTS idx_ledger_signer_nonce ON ledger_entries(ledger_id, signer_did, nonce);
+
+CREATE TABLE IF NOT EXISTS escrow_holds (
+  id             TEXT PRIMARY KEY,
+  order_id       TEXT NOT NULL,
+  buyer_did      TEXT NOT NULL,
+  seller_did     TEXT NOT NULL,
+  amount         INTEGER NOT NULL,
+  proposal_id    TEXT,                  -- settlement_ref → multisig 提案
+  status         TEXT NOT NULL DEFAULT 'held',  -- held | released | refunded
+  fund_entry_id  TEXT,                  -- buyer→custodian 的 ledger 条目
+  settle_entry_id TEXT,                 -- custodian→seller/buyer 的 ledger 条目
+  created_at_ms  INTEGER NOT NULL,
+  settled_at_ms  INTEGER
+);
+CREATE INDEX IF NOT EXISTS idx_holds_status ON escrow_holds(status);
+CREATE INDEX IF NOT EXISTS idx_holds_proposal ON escrow_holds(proposal_id);
+`;
+
+function applySchema(db) {
+  if (!db || typeof db.exec !== "function") {
+    throw new TypeError("applySchema: db.exec is required (better-sqlite3 or sql.js)");
+  }
+  db.exec(DDL);
+}
+
+module.exports = { DDL, applySchema };
diff --git a/packages/core-settlement/lib/signing.js b/packages/core-settlement/lib/signing.js
new file mode 100644
index 0000000000..df4f45a9a5
--- /dev/null
+++ b/packages/core-settlement/lib/signing.js
@@ -0,0 +1,67 @@
+"use strict";
+
+/**
+ * P1 结算核 — 转账日志条目的签名/验签。
+ *
+ * 设计文档 §8.2：联邦账本是「只追加的签名转账日志」——每笔由付款方签名，
+ * 节点只托管+排序，无有效签名伪造不了转账/增发。本模块提供条目的 canonical
+ * 字节、Ed25519 签名与验签（复用 core-mtc 的 ed25519 signer + JCS，与
+ * core-multisig 同源）。
+ *
+ * 域分隔：签名前 prefix "SETTLE:" 防与 MULTISIG / MTC 等其它协议签名跨用回放。
+ * canonical core 含 ledgerId — 把每笔转账绑定到具体联邦账本，防跨账本重放。
+ */
+
+const { jcs } = require("@chainlesschain/core-mtc/jcs");
+const ed25519Signer = require("@chainlesschain/core-mtc/signers/ed25519");
+
+const DOMAIN_PREFIX = Buffer.from("SETTLE:", "utf-8");
+const ALG = ed25519Signer.ALG;
+
+/**
+ * 条目签名输入 = DOMAIN_PREFIX || JCS({ledgerId, kind, from, to, amount, nonce})。
+ * sig 不入 core（producer + verifier 喂同样 core）。
+ * @param {{ledgerId:string, kind:"mint"|"transfer", from:(string|null), to:string, amount:number, nonce:string}} core
+ * @returns {Buffer}
+ */
+function canonicalizeEntry(core) {
+  if (!core || typeof core !== "object") {
+    throw new TypeError("canonicalizeEntry: core must be object");
+  }
+  const c = {
+    ledgerId: core.ledgerId,
+    kind: core.kind,
+    from: core.from == null ? null : core.from,
+    to: core.to,
+    amount: core.amount,
+    nonce: core.nonce,
+  };
+  return Buffer.concat([DOMAIN_PREFIX, jcs(c)]);
+}
+
+/**
+ * 用付款方（或 genesis）的 Ed25519 私钥签条目。
+ * @returns {Buffer} signature
+ */
+function signEntry(core, secretKey) {
+  return ed25519Signer.signRaw(canonicalizeEntry(core), secretKey);
+}
+
+/**
+ * 验条目签名。sig 接受 Buffer / Uint8Array（sql.js BLOB 读出是 Uint8Array）。
+ * @returns {boolean}
+ */
+function verifyEntry(core, sig, pubkeyJwk) {
+  const pk = ed25519Signer.jwkToPublicKey(pubkeyJwk);
+  if (!pk) return false;
+  const s = Buffer.isBuffer(sig) ? sig : Buffer.from(sig || []);
+  if (s.length !== 64) return false;
+  // 复用 core-mtc 已声明的 ed25519 验签（makeVerifier 内部即 ed25519.verify），不直接
+  // require("@noble/curves")——该包未在 core-settlement 声明，仅靠 monorepo hoisting
+  // 碰巧能用，独立发布安装会 Cannot find module。
+  const id = ed25519Signer.pubkeyId(pk);
+  const verify = ed25519Signer.makeVerifier(new Map([[id, pk]]));
+  return verify(canonicalizeEntry(core), { alg: ALG, pubkey_id: id, sig: s.toString("base64url") });
+}
+
+module.exports = { DOMAIN_PREFIX, ALG, canonicalizeEntry, signEntry, verifyEntry };
