@@ -0,0 +1,247 @@
+"use client";
+
+import { type ReactElement, useState } from "react";
+
+import EditRounded from "@mui/icons-material/EditRounded";
+import ErrorOutlineRounded from "@mui/icons-material/ErrorOutlineRounded";
+import { Box, Button, InputAdornment, Stack, TextField, Typography } from "@mui/material";
+
+import {
+  ACTION_ICON_PX,
+  ACTION_LABEL_PX,
+  ACTION_LETTER_SPACING,
+  BODY_STAT_CANCEL_LABEL,
+  BODY_STAT_EMPTY_ICON_PX,
+  BODY_STAT_EMPTY_PX,
+  BODY_STAT_SAVE_LABEL,
+  BODY_STAT_UNIT_PX,
+  BODY_STAT_VALUE_LETTER_SPACING,
+  BODY_STAT_VALUE_LINE_HEIGHT,
+  BODY_STAT_VALUE_PX,
+  CAPTION_LINE_HEIGHT,
+  CAPTION_PX,
+  CARD_PADDING,
+  CARD_RADIUS_PX,
+  EYEBROW_LETTER_SPACING,
+  EYEBROW_PX,
+  FONT_WEIGHT_DISPLAY,
+  FONT_WEIGHT_SEMI_BOLD,
+} from "../utils/athlete-profile.constants";
+
+export type BodyStatCardProps = {
+  value: number | null;
+  isSaving: boolean;
+  onSave: (value: number) => void;
+  parseValue: (draft: string) => number | null;
+  eyebrow: string;
+  unit: string;
+  caption: string;
+  emptyTitle: string;
+  emptyCaption: string;
+  setLabel: string;
+  editActionLabel: string;
+  setActionLabel: string;
+  fieldLabel: string;
+  inputStep: number;
+  inputMin: number;
+  inputMax: number;
+};
+
+export const BodyStatCard = ({
+  value,
+  isSaving,
+  onSave,
+  parseValue,
+  eyebrow,
+  unit,
+  caption,
+  emptyTitle,
+  emptyCaption,
+  setLabel,
+  editActionLabel,
+  setActionLabel,
+  fieldLabel,
+  inputStep,
+  inputMin,
+  inputMax,
+}: BodyStatCardProps): ReactElement => {
+  const [isEditing, setIsEditing] = useState(false);
+  const [draft, setDraft] = useState("");
+
+  const startEditing = (): void => {
+    setDraft(value != null ? String(value) : "");
+    setIsEditing(true);
+  };
+
+  const cancelEditing = (): void => {
+    setIsEditing(false);
+    setDraft("");
+  };
+
+  const handleSave = (): void => {
+    const parsed = parseValue(draft);
+
+    if (parsed == null) {
+      return;
+    }
+
+    onSave(parsed);
+    setIsEditing(false);
+  };
+
+  const isDraftValid = parseValue(draft) != null;
+  const actionLabel = value != null ? editActionLabel : setActionLabel;
+
+  return (
+    <Stack
+      spacing={1.5}
+      sx={(theme) => ({
+        flex: { md: 1 },
+        p: CARD_PADDING,
+        bgcolor: theme.palette.background.paper,
+        border: `1px solid ${theme.palette.divider}`,
+        borderRadius: `${CARD_RADIUS_PX}px`,
+      })}
+    >
+      <Stack direction="row" alignItems="center" justifyContent="space-between">
+        <Typography
+          component="div"
+          sx={(theme) => ({
+            fontSize: theme.typography.pxToRem(EYEBROW_PX),
+            fontWeight: FONT_WEIGHT_SEMI_BOLD,
+            letterSpacing: EYEBROW_LETTER_SPACING,
+            textTransform: "uppercase",
+            color: theme.palette.text.secondary,
+          })}
+        >
+          {eyebrow}
+        </Typography>
+
+        {!isEditing && (
+          <Button
+            size="small"
+            color="primary"
+            startIcon={<EditRounded sx={{ fontSize: ACTION_ICON_PX }} />}
+            onClick={startEditing}
+            sx={(theme) => ({
+              fontSize: theme.typography.pxToRem(ACTION_LABEL_PX),
+              fontWeight: FONT_WEIGHT_SEMI_BOLD,
+              letterSpacing: ACTION_LETTER_SPACING,
+              textTransform: "uppercase",
+            })}
+          >
+            {actionLabel}
+          </Button>
+        )}
+      </Stack>
+
+      {isEditing ? (
+        <Stack spacing={1}>
+          <TextField
+            label={fieldLabel}
