+            InputProps={{
+              endAdornment: <InputAdornment position="end">{unit}</InputAdornment>,
+            }}
+          />
+
+          <Button
+            variant="contained"
+            color="primary"
+            disabled={!isDraftValid || isSaving}
+            onClick={handleSave}
+          >
+            {BODY_STAT_SAVE_LABEL}
+          </Button>
+
+          <Button color="inherit" onClick={cancelEditing} sx={{ color: "text.secondary" }}>
+            {BODY_STAT_CANCEL_LABEL}
