diff --git a/apps/dashboard/src/app/(protected)/projects/[projectId]/builds/[buildId]/_components/contextual-toolbar.tsx b/apps/dashboard/src/app/(protected)/projects/[projectId]/builds/[buildId]/_components/contextual-toolbar.tsx
