+
+/**
+ * C-10/C-14: Safe CSV cell. Prevents CSV/formula injection (a customer named
+ * "=cmd|..." executing in the owner's Excel/Sheets) AND escapes quotes/commas/newlines.
+ * Always returns a double-quoted field.
+ * @param {*} value - raw cell value
+ * @returns {string} a quoted, injection-safe CSV field
+ */
+export function csvCell(value) {
+  let str = value === null || value === undefined ? '' : String(value);
+  // Neutralize formula triggers by prefixing with a single quote.
+  if (/^[=+\-@\t\r]/.test(str)) {
+    str = `'${str}`;
+  }
+  // Escape embedded double quotes by doubling them, then wrap in quotes.
+  return `"${str.replace(/"/g, '""')}"`;
+}
+
+// C-08: standard TCPA opt-out language appended to outbound SMS.
+export const SMS_OPT_OUT = '(Reply STOP to end)';
+
+/**
+ * C-08: Ensure an outbound SMS body carries opt-out language. Idempotent — if the
+ * body already mentions STOP/unsubscribe, it's returned unchanged.
+ * @param {string} body
+ * @returns {string} body guaranteed to contain opt-out language
+ */
+export function ensureOptOut(body) {
+  const str = body == null ? '' : String(body);
+  if (/\bstop\b|unsubscribe|opt[\s-]?out/i.test(str)) {
+    return str;
+  }
+  return `${str}\n\n${SMS_OPT_OUT}`;
+}

