+  let p = 0;
+  while (p < term.length && p < reading.length && term[p] === reading[p] && isKana(term[p])) p++;
+  let s = 0;
+  while (
+    s < term.length - p &&
+    s < reading.length - p &&
+    term[term.length - 1 - s] === reading[reading.length - 1 - s] &&
+    isKana(term[term.length - 1 - s])
