+  const segs: FuriganaSegment[] = [];
+  if (prefix) segs.push({ text: prefix });
+  if (core) segs.push({ text: core, reading: coreReading || undefined });
+  if (suffix) segs.push({ text: suffix });
+  return segs.length ? segs : [{ text: term }];
+}
