+        content: JSON.stringify({
+          previous,
+          reset: { used: 0, limit, resetAt },
+        }),
+      },
+    ],
+    metadata: {
+      success: true,
+      action: "reset",
+      tenantId,
+      resource,
+      limit,
+      resetAt,
+    },
+  };
